#include <iostream>
#include <memory>
using namespace std;

int main() {
    unique_ptr<int> uptr(new int(42));
    cout << "Unique: " << *uptr << endl;

    shared_ptr<int> sptr = make_shared<int>(100);
    cout << "Shared: " << *sptr << " count: " << sptr.use_count() << endl;
    {
        shared_ptr<int> sptr2 = sptr;
        cout << "Count: " << sptr.use_count() << endl;
    }
    cout << "Count: " << sptr.use_count() << endl;
    return 0;
}
